insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000003', 3, 'Sister City No More', 'Case 3', 'the right of victims and communities to public memory *versus* diplomatic harmony and a nation''s interest in how its past is portrayed.', 'the case looks like it''s about Japan, but its last third turns the question on the U.S. A team that condemns Japan while ignoring Confederate statues and plantation weddings will be caught in a double standard. Our claims are built to apply to both.', 'How should governments decide which events to memorialize in public spaces? (the case''s question)', true, '2026-11-01T00:00:00.000Z')
