insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000004', 4, 'Judging a Book by the Cover', 'Case 4', 'personal freedom to improve one''s appearance *versus* a culture that turns appearance into a moral duty and a market that profits from insecurity.', 'the case asks about a *duty*, but most of its evidence is about *benefits*. A benefit does not create a duty. Also, don''t argue against self-improvement as such, or a judge will ask about haircuts and braces.', 'Do we have a duty to be beautiful? (the case''s question)', true, '2026-11-01T00:00:00.000Z')
