insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000005', 5, 'The Gambler', 'Case 5', 'accurate public forecasting and individual freedom to trade *versus* turning war, death and political violence into profit opportunities that reward inside knowledge.', '"markets are accurate" is true and irrelevant to whether some markets are wrong. Also, don''t argue for a universal ban, or a judge will ask about weather or Oscars markets. Draw the line by kind of event.', 'Are there geopolitical issues that allow trading without moral harm? (closing question)', true, '2026-11-01T00:00:00.000Z')
