insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000007', 7, 'Equal Access Activism', 'Case 7', 'equal access as a civil right *versus* fairness to owners who lack knowledge, money or control over their buildings.', 'attacking Bouyer''s character. The case''s real question is the design of the incentive: what the system pays for. Also never frame disabled people as a "burden" businesses are forced to accommodate.', 'Is it acceptable to aim disability activism at small businesses as often as large ones?', true, '2026-11-01T00:00:00.000Z')
