insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000009', 9, 'GEM in the Rough', 'Case 9', 'righting a wartime taking *versus* preservation, global access and the law.', 'cultural nationalism ("objects belong to their nation") invites a slippery slope that empties every museum. Our case rests on a narrow four-part test instead.', 'Is it morally permissible for museums to retain artifacts that were previously stolen? (Dr. B''s version)', true, '2026-11-01T00:00:00.000Z')
