insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000010', 10, 'To Be, or Not to Be…Forgotten?', 'Case 10', 'a person''s chance to move on from their past *versus* the public''s right to accurate information and a free press.', 'treating all information alike. A court acquittal, a revenge-porn image, and a politician''s own old posts raise different questions. Tier them.', 'Do people have a right to be forgotten online?', true, '2026-11-01T00:00:00.000Z')
