insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000011', 11, 'The Cost of a Conscience', 'Case 11', 'lives saved by money from a tainted source *versus* the integrity of a mission and the trust it depends on.', 'a false dilemma between "take all money" and "refuse all tainted money." Also separate two questions: was the *money* made through wrongdoing, or is the *donor* personally compromised?', 'On what moral grounds should a nonprofit deny funds from organizations that undermine its mission? (Dr. B''s version)', true, '2026-11-01T00:00:00.000Z')
