insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000012', 12, 'Medicine and Misinformation', 'Case 12', 'protecting people from dangerous health falsehoods *versus* letting a party with its own interests decide what is true.', 'Article 13 is about *expertise* (who may present medical science); Article 4 is about *ideology* (who holds "correct" values). A team that treats them as one either defends ideological screening or condemns expertise checks. Name the split in the first minute.', 'Under what circumstances, if any, may a government regulate expression to curb misinformation? (Dr. B''s version)', true, '2026-11-01T00:00:00.000Z')
