insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000013', 13, 'Normally Distributed Violence', 'Case 13', 'holding speakers accountable for violence that runs through other people''s free choices *versus* protecting expression from a probability standard that whoever holds power could turn on critics.', 'First, the case blends moral responsibility with legal liability; our answer differs for each, so say which you mean. Second, the closing hypothetical is close to classic incitement, not stochastic terrorism; treat it separately.', 'Are those who spread hateful rhetoric responsible when it inspires others to commit violence? (Dr. B''s version)', true, '2026-11-01T00:00:00.000Z')
