insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000014', 14, 'The Allure of the Machine', 'Case 14', 'the freedom to build and use expressive, companion-like technology *versus* a duty of care to vulnerable users who form attachments to it.', 'the "books and video games" comparison. Static media say the same thing to everyone; a chatbot responds to *this* user, in real time, in a relationship. Don''t accept the analogy without distinguishing it.', 'What duties do AI companies have toward users?', true, '2026-11-01T00:00:00.000Z')
