insert into cases (id, number, title, case_set_page, crux, trap, closing_question, active, created_at) values ('c0000000-0000-4000-8000-000000000015', 15, 'Udderly Conflicted', 'Case 15', 'the moral significance of animals'' capacity to suffer *versus* a legal and economic system built on owning and using them.', '"personhood" means different things. Moral worth, membership in the moral community, and moral agency are different (Dr. B''s distinction). Animals can have moral worth without being moral agents who can have duties.', 'Should animals continue to be treated as property?', true, '2026-11-01T00:00:00.000Z')
